-- AI-Powered Criminal Network Analysis System
-- ALL DATA IS FICTIONAL / SYNTHETIC. DO NOT USE FOR REAL INVESTIGATION.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;

DROP TABLE IF EXISTS anomalies, entity_aliases, validations, alerts, relationships, case_links,
case_events, case_orgs, case_locations, case_phones, case_vehicles, person_orgs, person_vehicles,
person_phones, case_person, document_narratives, documents, cases, organizations, phones, vehicles,
locations, persons, users CASCADE;

CREATE TABLE users(
 user_id TEXT PRIMARY KEY, display_name TEXT, role TEXT, unit TEXT, status TEXT
);
CREATE TABLE persons(
 person_id TEXT PRIMARY KEY, full_name TEXT, alias TEXT, dob_year INT, role_profile TEXT, risk_tag TEXT, created_at DATE
);
CREATE TABLE locations(
 location_id TEXT PRIMARY KEY, name TEXT, city TEXT, state TEXT, lat DOUBLE PRECISION, lon DOUBLE PRECISION, type TEXT
);
CREATE TABLE vehicles(
 vehicle_id TEXT PRIMARY KEY, registration TEXT, make TEXT, model TEXT, color TEXT, status TEXT
);
CREATE TABLE phones(
 phone_id TEXT PRIMARY KEY, number TEXT, type TEXT, status TEXT
);
CREATE TABLE organizations(
 org_id TEXT PRIMARY KEY, name TEXT, type TEXT, city TEXT
);
CREATE TABLE cases(
 case_id TEXT PRIMARY KEY, case_number TEXT, title TEXT, case_type TEXT, police_station TEXT, city TEXT,
 opened_date DATE, status TEXT, priority TEXT, mo_code TEXT, summary TEXT, last_update DATE
);
CREATE TABLE documents(
 document_id TEXT PRIMARY KEY, case_id TEXT REFERENCES cases(case_id), document_type TEXT, title TEXT,
 file_name TEXT, source_type TEXT, created_at DATE, ocr_status TEXT, classification TEXT
);
CREATE TABLE document_narratives(
 document_id TEXT PRIMARY KEY REFERENCES documents(document_id), case_id TEXT REFERENCES cases(case_id), text TEXT
);
CREATE TABLE case_person(
 case_id TEXT REFERENCES cases(case_id), person_id TEXT REFERENCES persons(person_id), role TEXT,
 confidence NUMERIC, validation_status TEXT, source_document_id TEXT REFERENCES documents(document_id),
 PRIMARY KEY(case_id,person_id,role)
);
CREATE TABLE person_phones(
 person_id TEXT REFERENCES persons(person_id), phone_id TEXT REFERENCES phones(phone_id),
 valid_from DATE, valid_to DATE, confidence NUMERIC
);
CREATE TABLE person_vehicles(
 person_id TEXT REFERENCES persons(person_id), vehicle_id TEXT REFERENCES vehicles(vehicle_id),
 ownership_type TEXT, confidence NUMERIC
);
CREATE TABLE person_orgs(
 person_id TEXT REFERENCES persons(person_id), org_id TEXT REFERENCES organizations(org_id),
 role TEXT, confidence NUMERIC
);
CREATE TABLE case_vehicles(
 case_id TEXT REFERENCES cases(case_id), vehicle_id TEXT REFERENCES vehicles(vehicle_id),
 evidence_strength TEXT, source_document_id TEXT REFERENCES documents(document_id)
);
CREATE TABLE case_phones(
 case_id TEXT REFERENCES cases(case_id), phone_id TEXT REFERENCES phones(phone_id),
 relation TEXT, evidence_strength TEXT, source_document_id TEXT REFERENCES documents(document_id)
);
CREATE TABLE case_locations(
 case_id TEXT REFERENCES cases(case_id), location_id TEXT REFERENCES locations(location_id),
 relation TEXT, source_document_id TEXT REFERENCES documents(document_id)
);
CREATE TABLE case_orgs(
 case_id TEXT REFERENCES cases(case_id), org_id TEXT REFERENCES organizations(org_id),
 relation TEXT, source_document_id TEXT REFERENCES documents(document_id)
);
CREATE TABLE case_events(
 event_id TEXT PRIMARY KEY, case_id TEXT REFERENCES cases(case_id), event_type TEXT, event_date DATE,
 location_id TEXT REFERENCES locations(location_id), description TEXT
);
CREATE TABLE relationships(
 relationship_id TEXT PRIMARY KEY, source_type TEXT, source_id TEXT, target_type TEXT, target_id TEXT,
 relationship_type TEXT, confidence NUMERIC, evidence_status TEXT, source_document_id TEXT REFERENCES documents(document_id),
 explanation TEXT, first_seen DATE, last_seen DATE
);
CREATE TABLE case_links(
 link_id TEXT PRIMARY KEY, case_a TEXT REFERENCES cases(case_id), case_b TEXT REFERENCES cases(case_id),
 shared_entities INT, mo_similarity NUMERIC, temporal_proximity_days INT, spatial_proximity_km NUMERIC,
 semantic_similarity NUMERIC, overall_confidence NUMERIC, status TEXT
);
CREATE TABLE validations(
 validation_id TEXT PRIMARY KEY, relationship_id TEXT REFERENCES relationships(relationship_id), reviewer_role TEXT,
 action TEXT, comment TEXT, validated_at DATE
);
CREATE TABLE alerts(
 alert_id TEXT PRIMARY KEY, case_id TEXT REFERENCES cases(case_id), alert_type TEXT, severity TEXT,
 message TEXT, status TEXT
);
CREATE TABLE entity_aliases(
 alias_id TEXT PRIMARY KEY, canonical_id TEXT, observed_value TEXT, alias_type TEXT, confidence NUMERIC
);
CREATE TABLE anomalies(
 anomaly_id TEXT PRIMARY KEY, case_id TEXT REFERENCES cases(case_id), anomaly_type TEXT,
 score NUMERIC, explanation TEXT, status TEXT
);

-- Optional vector column for semantic retrieval. Populate with embeddings in the application layer.
ALTER TABLE document_narratives ADD COLUMN IF NOT EXISTS embedding vector(384);


CREATE INDEX idx_case_person_person ON case_person(person_id);
CREATE INDEX idx_case_person_case ON case_person(case_id);
CREATE INDEX idx_relationship_source ON relationships(source_type,source_id);
CREATE INDEX idx_relationship_target ON relationships(target_type,target_id);
CREATE INDEX idx_case_links_cases ON case_links(case_a,case_b);
CREATE INDEX idx_cases_status_priority ON cases(status,priority);
CREATE INDEX idx_events_case_date ON case_events(case_id,event_date);

